 1	const config = require("../config");
 2	const { HttpError } = require("../lib/httpError");
 3	
 4	// notes per user id, in memory
 5	const notesByUser = new Map();
 6	let nextId = 1;
 7	
 8	function list(userId) {
 9	  return notesByUser.get(userId) || [];
10	}
11	
12	function create(userId, text) {
13	  if (typeof text !== "string" || !text.trim()) {
14	    throw new HttpError(400, "note text is required");
15	  }
16	  if (text.length > config.maxNoteLength) {
17	    throw new HttpError(400, "note too long");
18	  }
19	  const notes = notesByUser.get(userId) || [];
20	  if (notes.length >= config.maxNotesPerUser) {
21	    throw new HttpError(400, "too many notes");
22	  }
23	  const note = { id: nextId++, text, createdAt: new Date().toISOString() };
24	  notes.push(note);
25	  notesByUser.set(userId, notes);
26	  return note;
27	}
28	
29	function remove(userId, noteId) {
30	  const notes = notesByUser.get(userId) || [];
31	  const idx = notes.findIndex((n) => n.id === noteId);
32	  if (idx === -1) throw new HttpError(404, "note not found");
33	  notes.splice(idx, 1);
34	}
35	
36	module.exports = { list, create, remove };
